"""Apply reviewed, subject-specific distractors without reinterpreting old answers."""
import pathlib,json,random,hashlib
data=pathlib.Path('src/data')
legacy=json.loads((data/'learning-previous-editions.json').read_text(encoding='utf-8'))
catalog=json.loads((data/'learning-catalog.json').read_text(encoding='utf-8'))
sets={}
def options(course,text):
    sets[course]={}
    for line in text.strip().splitlines():
        id,values=line.split(': ',1)
        values=values.split(' ¦ ')
        assert len(values)==3,(course,id)
        sets[course][id]=values

