for entry in catalog:
    if not any(c['id']==entry['id'] for c in legacy):continue
    old=next(c for c in legacy if c['id']==entry['id'])
    course=json.loads(json.dumps(old,ensure_ascii=False))
    expected={q['id'] for l in old['lessons'] for q in l['questions'] if q['kind']=='choice'}
    assert set(sets[old['id']])==expected,(old['id'],expected-set(sets[old['id']]),set(sets[old['id']])-expected)
    for lesson in course['lessons']:
        for q in lesson['questions']:
            if q['kind']!='choice':continue
            correct=q['options'][q['correct']]
            if correct in ('Да','Нет'):correct+=': '+q['explanation']
            wrong=sets[old['id']][q['id']]
            assert len(set(wrong+[correct]))==4,q['id']
            choices=[(correct,True)]+[(v,False) for v in wrong]
            random.Random(int(hashlib.sha256((old['id']+q['id']).encode()).hexdigest(),16)).shuffle(choices)
            q['options']=[v for v,_ in choices];q['correct']=next(i for i,(_,v) in enumerate(choices) if v)
            q['id']+='-v2'
    course['version']=old['version']+1
    (data/entry['file']).write_text(json.dumps(course,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Updated',sum(len(v) for v in sets.values()),'choice questions across',len(catalog),'courses')
